$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$p=Join-Path $root 'port-changes.json';$m=Get-Content $p -Raw|ConvertFrom-Json;$e=$m.files|Where-Object path -eq 'content/kinetics/chainConveyor/ChainConveyorRenderer.java';$e.changes=@($e.changes)+[pscustomobject]@{from='.setNormal(pNormal, 0.0F, 1.0F, 0.0F)';to='.setNormal(pNormal, 0.0F, 1.0F, 0.0F);'};$m|ConvertTo-Json -Depth 20|Set-Content $p -Encoding utf8;Write-Output 'Recorded Chain Conveyor vertex terminator.'
